toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #0F091A;
  font-family: "Syne, sans-serif";
}

>deepViolet = #0F091A;
>solarOrange = #FF8C00;
>cyberMint = #00FFB2;
>neonMagenta = #FF007A;
>chalkWhite = #FAF7F2;

rect #diamondOuter {
  at: center of canvas offset 0px -40px;
  size: 220px 220px;
  fill: none;
  stroke: >cyberMint;
  stroke-width: 4px;
  rotation: 45deg;
}

rect #diamondMiddle {
  at: center of #diamondOuter;
  size: 150px 150px;
  fill: none;
  stroke: >solarOrange;
  stroke-width: 6px;
  rotation: 45deg;
}

circle #coreSun {
  at: center of #diamondMiddle;
  size: 70px;
  fill: >neonMagenta;
}

text #brandName {
  at: below #diamondOuter offset 80px;
  content: "K W A N Z A";
  font-size: 32px;
  font-weight: 800;
  color: >chalkWhite;
}

text #descriptor {
  at: below #brandName offset 14px;
  content: "AFROFUTURIST INNOVATION NETWORK";
  font-size: 11px;
  font-weight: 700;
  color: >cyberMint;
}
